// FIS Pages Generator - creates 15 new pages by cloning an existing page's exact structure
// Run from the floridaimpactshield folder:  node gen_fis_pages.js
const fs = require('fs');
const path = require('path');
const BASE = 'C:\\Users\\randy\\Downloads\\floridaimpactshield-turnkey\\floridaimpactshield';
const PAGES_DIR = path.join(BASE, 'pages');
const DOMAIN = 'https://floridaimpactshield.com';
